-- AI reviews of briefs: one current review per brief, generated by the API with the caller's token.
-- Members read it; editors and admins generate and edit it, but only while the brief is editable, so a
-- review can't change under an approver's eyes once the brief is submitted (Phase 4b).

-- A target for composite foreign keys, so a child row can never point at a brief in another workspace.
alter table public.briefs add constraint briefs_id_workspace_id_key unique (id, workspace_id);

-- Bump the version only when the text changes: a review is "current" for one version of the text, and
-- workflow changes (Phase 4b) must not make it look outdated.
create or replace function private.briefs_touch()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (new.title, new.body) is distinct from (old.title, old.body) then
    new.version := old.version + 1;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create table public.brief_reviews (
  brief_id uuid primary key,
  workspace_id uuid not null,
  brief_version integer not null,
  state text not null check (state in ('pending', 'succeeded', 'failed')),
  result jsonb check (result is null or (jsonb_typeof(result -> 'areas') = 'object' and result ? 'summary')),
  error_code text check (error_code in ('model_failed', 'refused', 'timeout', 'invalid')),
  model text check (char_length(model) <= 100),
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  edited_at timestamptz,
  created_by uuid not null default private.current_user_id() references public.users (id),
  foreign key (brief_id, workspace_id) references public.briefs (id, workspace_id) on delete cascade,
  constraint brief_reviews_outcome check (
    (state = 'succeeded' and result is not null and error_code is null)
    or (state = 'failed' and error_code is not null)
    or state = 'pending'
  )
);
create index brief_reviews_workspace_id_idx on public.brief_reviews (workspace_id);
create index brief_reviews_created_by_idx on public.brief_reviews (created_by);

alter table public.brief_reviews enable row level security;

create policy brief_reviews_select_member on public.brief_reviews
  for select to authenticated
  using (workspace_id in (select private.member_workspace_ids()));

-- Writers of the workspace, and only while the brief itself is editable.
create policy brief_reviews_insert_writer on public.brief_reviews
  for insert to authenticated
  with check (
    workspace_id in (select private.workspace_ids_with_role(array['editor', 'admin']))
    and created_by = (select private.current_user_id())
    and exists (
      select 1 from public.briefs b
      where b.id = brief_id and b.workspace_id = brief_reviews.workspace_id and b.status in ('draft', 'changes_requested')
    )
  );

create policy brief_reviews_update_writer on public.brief_reviews
  for update to authenticated
  using (
    workspace_id in (select private.workspace_ids_with_role(array['editor', 'admin']))
    and exists (
      select 1 from public.briefs b
      where b.id = brief_id and b.workspace_id = brief_reviews.workspace_id and b.status in ('draft', 'changes_requested')
    )
  )
  with check (workspace_id in (select private.workspace_ids_with_role(array['editor', 'admin'])));

-- No delete: a review goes when its brief goes (the cascade doesn't need a grant).
grant select on public.brief_reviews to authenticated;
grant insert (brief_id, workspace_id, brief_version, state, started_at) on public.brief_reviews to authenticated;
grant update (brief_version, state, result, error_code, model, started_at, completed_at, edited_at) on public.brief_reviews to authenticated;
